// Generated by Gemini
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.type === "PROXY_FETCH") {
    const { url, options } = request;

    fetch(url, options)
      .then(async (res) => {
        const contentType = res.headers.get("content-type");
        let data;

        if (contentType && contentType.includes("application/json")) {
          data = await res.json();
        } else {
          data = await res.text();
        }

        sendResponse({
          success: res.ok,
          status: res.status,
          statusText: res.statusText,
          headers: Object.fromEntries(res.headers.entries()),
          data: data,
          error: !res.ok ? data?.message || res.statusText : null,
        });
      })
      .catch((error) => {
        sendResponse({
          success: false,
          error: error.message || "Network request failed",
        });
      });

    return true; // Keeps the message port open for asynchronous sendResponse
  }
});


// Generated by ChatGPT
function urlBase64ToUint8Array(base64) {
  const padding = "=".repeat((4 - base64.length % 4) % 4);
  const raw = atob(
    (base64 + padding).replace(/-/g, "+").replace(/_/g, "/"),
  );

  return Uint8Array.from(raw, (char) => char.charCodeAt(0));
}

chrome.runtime.onMessage.addListener(
  (message, _sender, sendResponse) => {
    if (message.type !== "SUBSCRIBE_TO_PUSH") return;

    (async () => {
      try {
        let subscription =
          await self.registration.pushManager.getSubscription();

        if (!subscription) {
          subscription =
            await self.registration.pushManager.subscribe({
              userVisibleOnly: true,
              applicationServerKey: urlBase64ToUint8Array(
                message.publicKey,
              ),
            });
        }

        sendResponse({
          success: true,
          subscription: subscription.toJSON(),
        });
      } catch (error) {
        console.error("Subscription failed:", error);
        sendResponse({ success: false });
      }
    })();

    return true;
  },
);

self.addEventListener("push", (event) => {
  console.log("PUSH EVENT RECEIVED");

  event.waitUntil(
    (async () => {
      const data = event.data?.json() ?? {};

      console.log("Push payload:", data);

      const notificationId = await chrome.notifications.create({
        type: "basic",
        iconUrl: chrome.runtime.getURL("lmlogo.png"),
        title: data.title ?? "Leetmates",
        message: data.body ?? "Test notification",
      });

      console.log("Notification created:", notificationId);
    })().catch((error) => {
      console.error("Failed to display notification:", error);
    }),
  );
});
